def card(slug, label, description, symbol):
    return (f'<div class="col-md-6 col-xl-3"><article class="guide-card">'
            f'<div class="symbol" aria-hidden="true">{symbol}</div><h3>{label}</h3>'
            f'<p>{description}</p><a class="stretched-link" href="{slug}.html" '
            f'aria-label="{escape(label)}"></a></article></div>')


def home_cards(lang):
    if lang == 'en':
        entries = [('create_activity', 'Create a hunt', 'Build roads, stages and clues from the course page.', '✎'),
                   ('custom_maps', 'Shape the map', 'Draw stage geometry and choose your map source.', '◇'),
                   ('opendata', 'Find discoveries', 'Use public knowledge as an authoring starting point.', '✦'),
                   ('play', 'Join the game', 'Learn the clues, location and QR flows.', '↗')]
    else:
        entries = [('create_activity', 'Crea una caza', 'Diseña caminos, etapas y pistas desde el curso.', '✎'),
                   ('custom_maps', 'Prepara el mapa', 'Dibuja etapas y elige una fuente cartográfica.', '◇'),
                   ('opendata', 'Encuentra ideas', 'Usa datos públicos como punto de partida.', '✦'),
                   ('play', 'Entra en el juego', 'Conoce las pistas, la posición y los QR.', '↗')]
    return ''.join(card(*entry) for entry in entries)


def navigation(lang, slug, asset):
    labels = NAV[lang]
    teacherlinks = ''.join(f'<li><a class="dropdown-item" href="{s}.html">{name}</a></li>'
                           for s, name in labels['teacherlinks'])
    studentlinks = ''.join(f'<li><a class="dropdown-item" href="{s}.html">{name}</a></li>'
                           for s, name in labels['studentlinks'])
    otherlang = f'../{slug}.html' if lang == 'es' else f'es/{slug}.html'
    active = lambda current: ' active' if slug == current else ''
    return f'''<a class="skip-link" href="#main">{'Saltar al contenido' if lang == 'es' else 'Skip to content'}</a>
<nav class="navbar navbar-expand-lg navbar-dark site-nav sticky-top" aria-label="{'Navegación principal' if lang == 'es' else 'Main navigation'}"><div class="nav-pegman-viewport" aria-hidden="true"><canvas class="header-pegman" data-pegman-canvas data-pegman-header data-model="{asset}models/pegman_hiker_all_animations_matte.glb"></canvas></div><div class="container">
  <a class="navbar-brand" href="index.html"><img class="brand-icon" src="{asset}images/main-icon-96x96.png" alt="" width="38" height="38"><span class="brand-title">Treasure Hunt<small>{'Aprender explorando' if lang == 'es' else 'Learn by exploring'}</small></span></a>
  <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#site-menu" aria-controls="site-menu" aria-expanded="false" aria-label="{'Abrir menú' if lang == 'es' else 'Open menu'}"><span class="navbar-toggler-icon"></span></button>
  <div class="collapse navbar-collapse" id="site-menu"><ul class="navbar-nav ms-auto align-items-lg-center">
    <li class="nav-item"><a class="nav-link{active('index')}" href="index.html">{labels['home']}</a></li>
    <li class="nav-item"><a class="nav-link{active('install')}" href="install.html">{labels['install']}</a></li>
    <li class="nav-item dropdown"><a class="nav-link dropdown-toggle" href="#" role="button" data-bs-toggle="dropdown" aria-expanded="false">{labels['teachers']}</a><ul class="dropdown-menu">{teacherlinks}</ul></li>
    <li class="nav-item dropdown"><a class="nav-link dropdown-toggle" href="#" role="button" data-bs-toggle="dropdown" aria-expanded="false">{labels['students']}</a><ul class="dropdown-menu">{studentlinks}</ul></li>
    <li class="nav-item"><a class="nav-link{active('player_modes')}" href="player_modes.html">{labels['modes']}</a></li>
    <li class="nav-item"><a class="nav-link lang-switch" href="{otherlang}" lang="{'en' if lang == 'es' else 'es'}">{labels['language']}</a></li>
  </ul></div></div></nav>'''


def footer(lang, asset):
    labels = NAV[lang]
    guide_links = ''.join(f'<a href="{slug}.html">{name}</a>' for slug, name in labels['teacherlinks'])
    student_links = ''.join(f'<a href="{slug}.html">{name}</a>' for slug, name in labels['studentlinks'])
    return f'''<footer class="site-footer"><div class="container"><div class="row g-4">
      <div class="col-lg-4"><a class="navbar-brand" href="index.html"><img class="brand-icon" src="{asset}images/main-icon-96x96.png" alt="" width="38" height="38"><span class="brand-title">Treasure Hunt</span></a><p class="mt-3">{labels['footercopy']}</p></div>
      <div class="col-sm-6 col-lg-3"><h3>{labels['teachers']}</h3>{guide_links}</div>
      <div class="col-sm-6 col-lg-2"><h3>{labels['students']}</h3>{student_links}</div>
      <div class="col-lg-3"><h3>{labels['resources']}</h3><a href="install.html">{labels['install']}</a><a href="player_modes.html">{labels['modes']}</a><a href="https://marketplace.moodle.com/plugins/mod_treasurehunt">Moodle Marketplace</a><a href="https://github.com/juacas/moodle-mod_treasurehunt">GitHub</a><a href="mailto:juanpablo.decastro@uva.es">juanpablo.decastro@uva.es</a></div>
    </div><div class="partner-row" aria-label="{'Instituciones' if lang == 'es' else 'Institutions'}"><span class="partner-logo"><img src="{asset}images/logo-cuatricromia-negativo.png" alt="Universidad de Valladolid" loading="lazy"></span><span class="partner-logo"><img src="{asset}images/eduvalab-logo.png" alt="EdUVALab" loading="lazy"></span></div>
    <div class="footer-bottom d-flex justify-content-between flex-wrap gap-2"><span>© Treasure Hunt · Universidad de Valladolid</span><span>{labels['rights']}</span></div></div></footer>'''


def article_body(lang, slug, data, asset):
    body = data['body'].replace('{asset}', asset)
    if slug == 'player_modes':
        caption = ('Animated Pegman model from the activity. It pauses when out of view.'
                   if lang == 'en' else
                   'Modelo Pegman animado de la actividad. Se detiene al salir de la vista.')
        model = (f'<div class="model-stage my-4"><canvas data-pegman-canvas '
                 f'data-model="{asset}models/pegman_hiker_all_animations_matte.glb" '
                 f'aria-label="Pegman 3D"></canvas><div class="model-caption">{caption}</div></div>')
        body = body.replace('<div class="player-modes-intro">',
                            '<div class="player-modes-intro row align-items-center g-4"><div class="col-lg-7">')
        body = body.replace('</p></div>\n     <h2 id="compare">',
                            '</p></div><div class="col-lg-5">' + model + '</div></div><h2 id="compare">')
    sections = re.findall(r'<h2 id="([^"]+)">(.+?)</h2>', body)
    links = ''.join(f'<a href="#{anchor}">{re.sub("<[^>]+>", "", heading)}</a>'
                    for anchor, heading in sections)
    label = NAV[lang]['guide']
    return f'''<header class="page-hero"><div class="container"><div class="breadcrumbs"><a href="index.html">{NAV[lang]['home']}</a> / {escape(data['title'])}</div><span class="eyebrow eyebrow-light">{NAV[lang]['teachers'] if slug in [s for s, _ in NAV[lang]['teacherlinks']] else NAV[lang]['students'] if slug in [s for s, _ in NAV[lang]['studentlinks']] else NAV[lang]['learn']}</span><h1>{escape(data['title'])}</h1><p>{escape(data['intro'])}</p></div></header>
    <main id="main" class="section section-white"><div class="container article-layout"><article class="article-content">{body}</article><aside class="toc" aria-label="{label}"><strong>{label}</strong>{links}</aside></div></main>'''


def home_body(lang, data, asset):
    body = data['body'].replace('{asset}', asset).replace('{cards}', home_cards(lang))
    primary = 'Create a hunt' if lang == 'en' else 'Crear una caza'
    secondary = 'See how to play' if lang == 'en' else 'Descubre cómo jugar'
    sticker = 'Explore · Discover · Learn' if lang == 'en' else 'Explora · Descubre · Aprende'
    videolabel = 'Watch the video' if lang == 'en' else 'Ver el vídeo'
    videotitle = 'How TreasureHunt for Moodle Works' if lang == 'en' else 'Cómo funciona TreasureHunt para Moodle'
    return f'''<main id="main"><section class="hero section"><div class="container"><div class="row align-items-center g-5"><div class="col-lg-6"><span class="eyebrow eyebrow-light">A Moodle adventure · Una aventura Moodle</span><h1>{escape(data['title'])}</h1><p class="lead mt-4">{escape(data['intro'])}</p><div class="d-flex flex-wrap gap-3 mt-4"><a class="btn btn-primary" href="create_activity.html">{primary} →</a><a class="btn btn-outline-light" href="play.html">{secondary}</a></div></div><div class="col-lg-6"><div class="hero-image-wrap hero-video-wrap"><button class="hero-video-launch" type="button" data-video-id="jADvcH5q1sk" data-video-title="{videotitle}" aria-label="{videolabel}: {videotitle}"><img class="hero-photo" src="{asset}images/{data['image']}" alt=""><span class="hero-video-action" aria-hidden="true"><span class="hero-video-play">▶</span><span>{videolabel}</span></span></button><div class="hero-sticker">{sticker}</div></div></div></div></div></section>{body}</main>'''


def render(lang, slug, data):
    asset = '../assets/' if lang == 'es' else 'assets/'
    content = home_body(lang, data, asset) if slug == 'index' else article_body(lang, slug, data, asset)
    description = escape(data['intro'], quote=True)
    modelscripts = (f'<script src="{asset}js/three-pegman.min.js" defer></script>'
                    f'<script src="{asset}js/site.js" defer></script>')
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{description}"><meta name="theme-color" content="#102d29"><title>{escape(data['title'])} · Treasure Hunt</title><link rel="icon" href="{asset}images/main-icon-96x96.png"><link rel="stylesheet" href="{asset}css/bootstrap.min.css"><link rel="stylesheet" href="{asset}css/site.css"></head>
<body>{navigation(lang, slug, asset)}{content}{footer(lang, asset)}<script src="{asset}js/bootstrap.bundle.min.js" defer></script>{modelscripts}</body></html>'''


def build():
    for (lang, slug), data in PAGES.items():
        target = ROOT / ('es' if lang == 'es' else '') / (slug + '.html')
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(render(lang, slug, data) + '\n', encoding='utf-8')
        print(target.relative_to(ROOT))


if __name__ == '__main__':
    build()
